const current=()=>db.events.find(e=>e.id===db.active)||null,team=(id,e=current())=>e?.teams.find(t=>t.id===id),tn=(id,e=current())=>team(id,e)?.name||'Awaiting contender',match=id=>current()?.matches.find(m=>m.id===id),organizer=()=>role==='organizer';
function migrate(old){if(old.appVersion===2)return old;if(!old.config||!Array.isArray(old.teams))return db;let e={id:uid(),name:old.config.name||'Tournament',config:{...defaults(),game:old.config.game||'',rosterSize:old.config.rosterSize||5,maxTeams:old.config.maxTeams??8,date:old.config.date||'',deadline:old.config.deadline||'',registration:old.config.registration||'open'},teams:old.teams.map(t=>({...t,contact:t.contact||'',logo:t.logo||'',notes:t.notes||'',color:t.color||'#b8a1ff',createdAt:old.savedAt||new Date().toISOString()})),matches:(old.matches||[]).map((m,i)=>({...m,name:'Match '+m.n,round:i<4?0:i<6?1:2,group:i<4?'Quarterfinals':i<6?'Semifinals':'Grand final',kind:'bracket',ranked:true,auto:false,settled:!!m.winner,aKnown:i<4||!!m.a,bKnown:i<4||!!m.b,next:i<4?(old.matches||[])[4+Math.floor(i/2)]?.id:i<6?(old.matches||[])[6]?.id:null,nextSlot:i%2===0?'a':'b',parents:i<4?[]:i<6?[(old.matches||[])[(i-4)*2]?.id,(old.matches||[])[(i-4)*2+1]?.id]:[(old.matches||[])[4]?.id,(old.matches||[])[5]?.id],checkIn:{a:false,b:false},submissions:(m.submissions||[]).map(s=>({...s,status:m.winner?'approved':'pending',note:s.note||'',reviewNote:s.reviewNote||''})),bestOf:3,scoreMode:'points',notes:''})),disputes:(old.disputes||[]).map(d=>({...d,title:d.title||'Match dispute',priority:'medium',owner:'',due:'',history:[]})),announcements:[],activity:[]};return {...db,events:[e],active:e.id,savedAt:old.savedAt}}
async function init(){try{storage=await new Promise((res,rej)=>{let r=indexedDB.open('ArenaHubDevice',1);r.onupgradeneeded=()=>r.result.createObjectStore('workspace');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error);r.onblocked=()=>rej(Error('Database blocked'))});let saved=await new Promise((res,rej)=>{let r=storage.transaction('workspace').objectStore('workspace').get(KEY);r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)});if(saved)db=migrate(saved);committed=structuredClone(db);lastSaved=db.savedAt||null;ready=true;render()}catch{ready=true;render();toast('Storage unavailable. Enable browser storage to save your records.')}}
