function log(text,e=current()){if(e)e.activity.unshift({id:uid(),text,at:new Date().toISOString()})}
function toast(t){$('toast').textContent=t;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4500)}
function allowed(){if(!organizer()){toast('Open the Organizer workspace for this action.');return false}return true}
function go(p){page=p;query='';$('globalSearch').value='';render();$('sidebar').classList.remove('expanded');$('menuToggle').setAttribute('aria-expanded','false')}
function closeDialog(){if($('dialog').open)$('dialog').close();$('dialogBody').innerHTML=''}
function openDialog(title,body){$('dialogTitle').textContent=title;$('dialogBody').innerHTML=body;$('dialog').showModal()}
function pastDeadline(e=current()){if(!e?.config.deadline)return false;let d=new Date(),today=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');return today>e.config.deadline}
