function lobby(){let e=current(),done=e?e.matches.filter(m=>m.settled&&!m.auto).length:0,pending=e?e.matches.filter(m=>['pending','disputed'].includes(status(m))).length:0,issues=e?e.disputes.filter(d=>d.status!=='resolved').length:0;let title=db.headline.split('\n');let hero=`<section class="hero"><div class="herocopy"><div class="caps"><span class="pulseDot"></span> YOUR WORLD. YOUR RULES.</div><h1>${E(title[0]||'BUILD YOUR SQUAD.')}<br><span>${E(title[1]||'OWN THE ARENA.')}</span></h1><p>Build the competition. Control every round.<br>From first entry to the final victory.</p><div class="actions"><button class="primary" onclick="${e?"go('register')":"eventForm()"}">${e?'ENTER YOUR SQUAD ↗':'CREATE TOURNAMENT ↗'}</button><button onclick="${e?"go('matches')":"go('personalize')"}">${e?'OPEN MATCH CENTER':'PERSONALIZE YOUR ARENA'}</button></div><div class="heroMeta">${e?`${E(e.config.game||'Custom game')} / ${e.config.format==='knockout'?'KNOCKOUT':'ROUND ROBIN'} / ${e.config.maxTeams?e.config.maxTeams+' TEAM LIMIT':'OPEN TEAM LIMIT'}`:'MULTI-TOURNAMENT / FLEXIBLE ROSTERS / DEVICE STORAGE'}</div></div><div class="heroMark">${E(db.brand)} / COMMAND</div></section><section class="stats"><div class="stat"><div class="statLabel">01 / SQUADS</div><b>${e?.teams.length||0}</b><span>${e?e.teams.filter(t=>t.status==='approved').length:0} approved · ${e?.config.maxTeams||'No fixed'} limit</span></div><div class="stat"><div class="statLabel">02 / MATCHES</div><b>${done}<span class="countSuffix"> / ${e?e.matches.filter(m=>!m.auto).length:0}</span></b><span>Completed matchups</span></div><div class="stat"><div class="statLabel">03 / REVIEW</div><b>${pending}</b><span>Match results awaiting action</span></div><div class="stat"><div class="statLabel">04 / DISPUTES</div><b>${issues}</b><span>Open / in-review tickets</span></div></section>`;let next=e?e.matches.filter(m=>m.time&&!m.settled).sort((a,b)=>new Date(a.time)-new Date(b.time)).slice(0,4):[],final=e?.matches.find(m=>m.kind==='bracket'&&!m.next),champ=final?.winner;let extras=e?`<div class="two"><section class="card"><div class="sectionLabel">COMPETITION STATUS</div><h2>${E(e.name)}</h2>${champ?`<div class="champion"><div class="caps">YOUR CHAMPION</div><h2>${E(tn(champ))}</h2></div>`:`<div class="kv"><span>Format</span><strong>${e.config.format==='knockout'?'Single elimination':'Round robin'}</strong></div><div class="kv"><span>Roster size</span><strong>${e.config.rosterSize} players / squad</strong></div><div class="kv"><span>Score rules</span><strong>${e.config.scoreMode==='series'?'Best of '+e.config.bestOf:'Points scoring'}</strong></div><div class="kv"><span>Team entry</span><strong>${locked(e)?'Locked':'Open'}</strong></div>`}<div class="actions"><button onclick="go('settings')">EVENT CONTROL →</button><button onclick="go('leaderboard')">LEADERBOARD →</button></div></section><section class="card"><div class="sectionLabel">NEXT UP</div><h2>Upcoming battles</h2>${next.length?next.map(m=>`<div class="event"><div><strong>${E(tn(m.a))} vs ${E(tn(m.b))}</strong><span>${E(timeText(m))}</span></div><span class="badge ${status(m)}">${status(m)}</span></div>`).join(''):empty('Your scheduled matches will appear here.')}</section></div><div class="two" style="margin-top:20px"><section class="card"><div class="sectionLabel">LATEST INTEL</div><h2>Event bulletins</h2>${e.announcements.slice().sort((a,b)=>Number(b.pinned)-Number(a.pinned)).slice(0,3).map(n=>`<div class="event"><div><strong>${E(n.title)}</strong><p>${E(n.body.slice(0,140))}</p></div><span class="badge">${n.pinned?'Pinned':E(n.priority)}</span></div>`).join('')||empty('Publish event updates, rule changes and match notices.')}<button onclick="go('announcements')">OPEN BULLETINS →</button></section><section class="card"><div class="sectionLabel">COMMAND LOG</div><h2>Recent activity</h2><ul class="activity">${e.activity.slice(0,5).map(a=>`<li>${E(a.text)}<time>${E(new Date(a.at).toLocaleString())}</time></li>`).join('')||'<li>No actions recorded yet.</li>'}</ul></section></div>`:`<div class="featurestrip"><section class="card"><div class="caps">01 / BUILD</div><h3>Multiple tournaments</h3><small>Keep separate teams, matches and rules for every event.</small></section><section class="card"><div class="caps">02 / CONFIGURE</div><h3>Make it your own</h3><small>Change games, roster sizes, team limits, score rules and branding.</small></section><section class="card"><div class="caps">03 / CONTROL</div><h3>Every result matters</h3><small>Review evidence, resolve disputes and keep a device backup.</small></section></div>`;return hero+extras+`<div class="sectionhead"><h2>YOUR TOURNAMENTS <span class="noticeCount">/ ${db.events.length}</span></h2>${organizer()?'<button class="primary" onclick="eventForm()">+ NEW TOURNAMENT</button>':''}</div><div class="cards">${db.events.map(x=>`<article class="card eventcard ${x.id===db.active?'active':''}"><div class="cardTop"><span class="badge">${E(x.config.game||'Custom game')}</span><span class="badge">${x.id===db.active?'Active':'Saved'}</span></div><h3>${E(x.name)}</h3><p>${x.config.format==='knockout'?'Knockout':'Round robin'} · ${x.config.rosterSize}-player rosters</p><div class="mini"><span><b>${x.teams.length}</b>Squads</span><span><b>${x.matches.length}</b>Matches</span><span><b>${x.disputes.filter(d=>d.status!=='resolved').length}</b>Open tickets</span></div><div class="actions"><button onclick="switchEvent('${x.id}')">OPEN EVENT →</button>${organizer()?`<button class="danger" onclick="deleteEvent('${x.id}')">Delete</button>`:''}</div></article>`).join('')||empty('No tournaments yet. Create your first competition.')}</div>`}
async function switchEvent(id){closeDialog();db.active=id;if(!await save())return;go('overview')}
async function deleteEvent(id){if(!allowed()||!confirm('Delete this tournament and all its teams, matches and evidence? Export a backup first if needed.'))return;db.events=db.events.filter(e=>e.id!==id);if(db.active===id)db.active=db.events[0]?.id||null;if(!await save())return;go('overview');toast('Tournament deleted.')}
function eventFields(e){let c=e?.config||defaults();return `<label for="eventName">Tournament name</label><input id="eventName" required maxlength="80" value="${E(e?.name||'')}" placeholder="Name your competition"><label for="gameName">Game / discipline</label><input id="gameName" required maxlength="60" list="games" value="${E(c.game)}" placeholder="Choose or type any game"><datalist id="games"><option>Valorant</option><option>Counter-Strike 2</option><option>Mobile Legends</option><option>Free Fire</option><option>PUBG Mobile</option><option>EA Sports FC</option><option>Rocket League</option><option>Chess</option></datalist><div class="formgrid"><div><label for="rosterSize">Players per squad</label><input id="rosterSize" type="number" min="1" max="100" step="1" required value="${c.rosterSize}"></div><div><label for="maxTeams">Squad limit (0 = no fixed limit)</label><input id="maxTeams" type="number" min="0" step="1" required value="${c.maxTeams}"></div><div><label for="format">Competition format</label><select id="format"><option value="knockout" ${c.format==='knockout'?'selected':''}>Single elimination + automatic byes</option><option value="roundrobin" ${c.format==='roundrobin'?'selected':''}>Round robin / league</option></select></div><div><label for="scoreMode">Scoring mode</label><select id="scoreMode"><option value="points" ${c.scoreMode==='points'?'selected':''}>Points / game score</option><option value="series" ${c.scoreMode==='series'?'selected':''}>Best-of series</option></select></div><div><label for="bestOf">Series length (odd number)</label><input id="bestOf" type="number" min="1" step="2" value="${c.bestOf}" required></div><div><label for="winPoints">Leaderboard points per win</label><input id="winPoints" type="number" min="0" step="1" value="${c.winPoints}" required></div><div><label for="drawPoints">Leaderboard points per draw</label><input id="drawPoints" type="number" min="0" step="1" value="${c.drawPoints}" required></div><div><label for="eventDate">Start date (optional)</label><input id="eventDate" type="date" value="${E(c.date)}"></div><div><label for="deadline">Entry deadline (optional)</label><input id="deadline" type="date" value="${E(c.deadline)}"></div><div><label for="eventAccent">Event accent color</label><input id="eventAccent" class="colorInput" type="color" value="${c.accent||'#b8a1ff'}"></div></div><div class="checklist"><label><input id="useEventAccent" type="checkbox" ${c.accent?'checked':''}>Use a custom event accent</label><label><input id="allowDraw" type="checkbox" ${c.allowDraw?'checked':''}>Allow draws in league / friendly points matches</label><label><input id="proofRequired" type="checkbox" ${c.proofRequired?'checked':''}>Require screenshot evidence for score submissions</label><label><input id="lockRosters" type="checkbox" ${c.lockRosters?'checked':''}>Lock rosters after fixtures are generated</label></div><label for="customRules">Additional tournament rules</label><textarea id="customRules" maxlength="10000" placeholder="Your conduct, check-in and competition rules">${E(c.rules)}</textarea><p id="eventError" class="error" role="alert"></p><button class="primary" type="submit">${e?'SAVE EVENT SETTINGS':'CREATE TOURNAMENT →'}</button>`}
function eventForm(){if(!allowed())return;openDialog('CREATE YOUR COMPETITION',`<form id="newEventForm">${eventFields(null)}</form>`);wireEventForm('newEventForm',null)}
function wireEventForm(form,id){$(form).onsubmit=async ev=>{ev.preventDefault();let old=id?db.events.find(e=>e.id===id):null,c={...(old?.config||defaults()),game:$('gameName').value.trim(),rosterSize:Number($('rosterSize').value),maxTeams:Number($('maxTeams').value),format:$('format').value,scoreMode:$('scoreMode').value,bestOf:Number($('bestOf').value),winPoints:Number($('winPoints').value),drawPoints:Number($('drawPoints').value),date:$('eventDate').value,deadline:$('deadline').value,allowDraw:$('allowDraw').checked,proofRequired:$('proofRequired').checked,lockRosters:$('lockRosters').checked,accent:$('useEventAccent').checked?$('eventAccent').value:'',rules:$('customRules').value.trim()},name=$('eventName').value.trim(),err=$('eventError');if(!name||!c.game){err.textContent='Enter a tournament name and game.';return}if(!Number.isInteger(c.rosterSize)||c.rosterSize<1||c.rosterSize>100||!Number.isSafeInteger(c.maxTeams)||c.maxTeams<0||!Number.isSafeInteger(c.bestOf)||c.bestOf<1||c.bestOf%2!==1||![c.winPoints,c.drawPoints].every(n=>Number.isSafeInteger(n)&&n>=0)){err.textContent='Check the numeric settings. Roster size is 1–100; series length must be a positive odd number.';return}if(c.date&&c.deadline&&c.deadline>c.date){err.textContent='Entry deadline cannot be after the event start date.';return}if(old&&old.teams.length&&old.config.rosterSize!==c.rosterSize){err.textContent='Roster size cannot change while squads exist. Create another tournament or remove its squads first.';return}if(old&&c.maxTeams&&old.teams.filter(t=>t.status!=='rejected').length>c.maxTeams){err.textContent='The squad limit is smaller than the existing active registrations.';return}if(old?.matches.length&&['format','scoreMode','bestOf','allowDraw'].some(k=>old.config[k]!==c[k])){err.textContent='Clear fixtures before changing format or match scoring. Other event settings can still change.';return}if(old){old.name=name;old.config=c;log('Event settings updated',old)}else{let e={id:uid(),name,config:c,teams:[],matches:[],disputes:[],announcements:[],activity:[],createdAt:new Date().toISOString()};db.events.push(e);db.active=e.id;log('Tournament created',e)}if(!await save())return;closeDialog();go(old?'settings':'overview');toast(old?'Event settings saved.':'Your tournament is ready.')}}
function teamPage(){let e=current();return heading('SQUAD COMMAND',db.labels.teams,'Build, approve and organize your contenders.',role!=='viewer'?'<button class="primary" onclick="go(\'register\')">+ ADD SQUAD</button>':'')+`<div class="filters"><input id="teamSearch" type="search" placeholder="Search squad or captain" aria-label="Search squads"><select id="teamFilter" aria-label="Filter squad status"><option value="all">All statuses</option><option>pending</option><option>approved</option><option>rejected</option></select></div><div class="cards" id="teamList">${teamCards(e.teams)}</div>`}
function teamCards(rows){let e=current();return rows.map(t=>`<article class="card eventcard"><div class="teamhead"><div class="logoWrap">${t.logo?`<img class="tlogo" src="${t.logo}" alt="${E(t.name)} logo">`:`<div class="avatar" style="border-color:${E(t.color||'#b8a1ff')}">${E(t.name.split(' ').map(x=>x[0]).join('').slice(0,2))}</div>`}<div><h3>${E(t.name)}</h3><small>${E(t.captain)}</small></div></div><span class="badge ${t.status}">${t.status}</span></div><ul class="roster">${t.players.map(p=>`<li><span>${E(p.name)}</span><span class="muted">${E(p.pid)}</span></li>`).join('')}</ul>${t.contact?`<p><small>Contact: ${E(t.contact)}</small></p>`:''}${t.notes?`<p class="longText"><small>${E(t.notes)}</small></p>`:''}<div class="actions">${role!=='viewer'?`<button onclick="editTeam('${t.id}')" ${locked()?'disabled':''}>Edit squad</button>`:''}${organizer()?`<button class="danger" onclick="deleteTeam('${t.id}')">Delete</button>${t.status!=='approved'?`<button onclick="approveTeam('${t.id}')">Approve</button>`:''}${t.status!=='rejected'?`<button onclick="rejectTeam('${t.id}')">Reject</button>`:''}`:''}</div></article>`).join('')||empty('No squads here yet. Add your first registration.')}
function filterTeamCards(){let q=$('teamSearch').value.toLowerCase(),f=$('teamFilter').value;$('teamList').innerHTML=teamCards(current().teams.filter(t=>(t.name+' '+t.captain).toLowerCase().includes(q)&&(f==='all'||t.status===f)))}
function rosterForm(t=null){let n=current().config.rosterSize;return `<label for="teamName">Squad name</label><input id="teamName" required maxlength="80" value="${E(t?.name||'')}" placeholder="Name your squad"><label for="captainName">Captain name</label><input id="captainName" required maxlength="80" value="${E(t?.captain||'')}"><div class="formgrid"><div><label for="contact">Contact (optional)</label><input id="contact" maxlength="120" value="${E(t?.contact||'')}" placeholder="Email or contact handle"></div><div><label for="teamColor">Squad color</label><input id="teamColor" class="colorInput" type="color" value="${t?.color||'#b8a1ff'}"></div></div><label for="teamLogo">Squad logo (optional · PNG/JPG/WebP · up to 1 MB)</label><input id="teamLogo" type="file" accept="image/png,image/jpeg,image/webp">${t?.logo?`<img class="logoPreview" src="${t.logo}" alt="Current squad logo"><div class="checklist"><label><input type="checkbox" id="removeLogo">Remove existing logo</label></div>`:''}<div class="fieldgroup"><h3>${n}-PLAYER ROSTER</h3>${Array.from({length:n},(_,i)=>`<div class="rosterform"><div><label for="pn${i}">Player ${i+1} name</label><input id="pn${i}" required maxlength="80" value="${E(t?.players[i]?.name||'')}"></div><div><label for="pi${i}">Player ${i+1} ID</label><input id="pi${i}" required maxlength="80" value="${E(t?.players[i]?.pid||'')}"></div></div>`).join('')}</div><label for="teamNotes">Squad notes (optional)</label><textarea id="teamNotes" maxlength="2000">${E(t?.notes||'')}</textarea><p id="teamError" class="error" role="alert"></p><button type="submit" class="primary">${t?'SAVE SQUAD':'SUBMIT SQUAD ENTRY →'}</button>`}
function registerPage(){let e=current();return heading('TEAM ENTRY','ASSEMBLE YOUR CONTENDERS.','Your squad identity, your players and your roster.')+`<div class="two"><section class="card">${role==='viewer'?empty('Open Captain or Organizer workspace to register.'):locked()?empty('Squad entry and editing are currently locked. Check event controls.'): `<form id="entryForm">${rosterForm()}</form>`}</section><section class="card"><div class="sectionLabel">ENTRY REQUIREMENTS</div><h2>${E(e.name)}</h2><div class="kv"><span>Game</span><strong>${E(e.config.game)}</strong></div><div class="kv"><span>Roster</span><strong>${e.config.rosterSize} players</strong></div><div class="kv"><span>Squad capacity</span><strong>${e.teams.filter(t=>t.status!=='rejected').length} / ${e.config.maxTeams||'Open limit'}</strong></div><div class="kv"><span>Entry deadline</span><strong>${E(e.config.deadline||'Not set')}</strong></div><ol class="rules"><li>Squad names and player IDs must be unique within this tournament.</li><li>New and edited rosters require organizer approval.</li><li>Your registration is saved on this device after submission completes.</li></ol>${e.config.rules?`<h3>Event rules</h3><div class="bodyText">${E(e.config.rules)}</div>`:''}</section></div>`}
async function readImage(file,limit){if(!file)return '';if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>limit)throw Error('Use a PNG/JPG/WebP image within the size limit.');let data=await new Promise((res,rej)=>{let r=new FileReader();r.onload=()=>res(r.result);r.onerror=rej;r.readAsDataURL(file)});await new Promise((res,rej)=>{let im=new Image();im.onload=res;im.onerror=()=>rej(Error('The file is not a readable image.'));im.src=data});return data}
function wireTeamForm(form,tid){$(form).onsubmit=async ev=>{ev.preventDefault();let e=current(),err=$('teamError');if(role==='viewer'||locked()){err.textContent='Squad entry is locked.';return}let name=$('teamName').value.trim(),captain=$('captainName').value.trim(),players=Array.from({length:e.config.rosterSize},(_,i)=>({name:$('pn'+i).value.trim(),pid:$('pi'+i).value.trim()})),others=e.teams.filter(t=>t.id!==tid),ids=players.map(p=>p.pid.toLowerCase());if(!name||!captain||players.some(p=>!p.name||!p.pid)){err.textContent='Complete every squad and player field.';return}if(others.some(t=>t.name.toLowerCase()===name.toLowerCase())){err.textContent='This squad name already exists.';return}if(new Set(ids).size!==ids.length||others.some(t=>t.players.some(p=>ids.includes(p.pid.toLowerCase())))){err.textContent='Player IDs must be unique within and across squads.';return}if(!tid&&e.config.maxTeams&&e.teams.filter(t=>t.status!=='rejected').length>=e.config.maxTeams){err.textContent='This event has reached its configured squad limit.';return}let logo=tid?team(tid).logo:'';try{let file=$('teamLogo').files[0];if(file)logo=await readImage(file,1024*1024);else if($('removeLogo')?.checked)logo=''}catch(x){err.textContent=x.message;return}let record={name,captain,players,logo,contact:$('contact').value.trim(),color:$('teamColor').value,notes:$('teamNotes').value.trim(),status:'pending'};if(tid)Object.assign(team(tid),record);else e.teams.push({id:uid(),...record,createdAt:new Date().toISOString()});log((tid?'Squad updated: ':'Squad registered: ')+name);if(!await save())return;closeDialog();go('teams');toast('Squad saved. Awaiting organizer approval.')}}
function editTeam(tid){if(role==='viewer'||locked()){toast('Roster editing is locked. Check event controls.');return}openDialog('EDIT YOUR SQUAD',`<form id="editSquadForm">${rosterForm(team(tid))}</form>`);wireTeamForm('editSquadForm',tid)}
async function deleteTeam(tid){if(!allowed())return;if(current().matches.some(m=>m.a===tid||m.b===tid)){toast('This squad appears in fixtures. Clear its event fixtures before deleting.');return}if(!confirm('Delete '+tn(tid)+' and its roster?'))return;let name=tn(tid);current().teams=current().teams.filter(t=>t.id!==tid);log('Squad deleted: '+name);if(!await save())return;render();toast('Squad deleted.')}
async function approveTeam(tid){if(!allowed())return;let e=current(),t=team(tid);if(t.status==='rejected'&&e.config.maxTeams&&e.teams.filter(x=>x.status!=='rejected').length>=e.config.maxTeams){toast('The squad limit has been reached.');return}t.status='approved';log('Squad approved: '+t.name);if(!await save())return;render();toast('Squad approved.')}
async function rejectTeam(tid){if(!allowed())return;if(current().matches.some(m=>m.a===tid||m.b===tid)){toast('Clear fixtures before rejecting a participating squad.');return}team(tid).status='rejected';log('Squad rejected: '+tn(tid));if(!await save())return;render();toast('Squad rejected.')}
function playerPage(){return heading('PLAYER INDEX','EVERY CONTENDER, ONE PLACE.','Search players by name, in-game ID or squad.')+`<div class="filters"><input id="playerSearch" type="search" placeholder="Search your players" aria-label="Search players"></div><div id="playerTable">${playerTable('')}</div>`}
function playerTable(q){let rows=current().teams.flatMap(t=>t.players.map(p=>({...p,team:t.name,captain:t.captain,status:t.status}))).filter(p=>(p.name+' '+p.pid+' '+p.team).toLowerCase().includes(q.toLowerCase()));return rows.length?`<div class="tablewrap"><table class="table"><thead><tr><th>Player</th><th>In-game ID</th><th>Squad</th><th>Captain</th><th>Entry status</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${E(p.name)}</td><td>${E(p.pid)}</td><td>${E(p.team)}</td><td>${E(p.captain)}</td><td><span class="badge ${p.status}">${p.status}</span></td></tr>`).join('')}</tbody></table></div><p><small>${rows.length} matching players</small></p>`:empty('No matching players.')}
function filterPlayers(){$('playerTable').innerHTML=playerTable($('playerSearch').value)}
function createMatch(e,a,b,extra={}){return {id:uid(),name:'Match '+(e.matches.length+1),a,b,aKnown:true,bKnown:true,kind:'friendly',ranked:false,round:0,group:'Custom match',parents:[],next:null,nextSlot:null,settled:false,auto:false,winner:null,score:null,time:null,duration:60,bestOf:e.config.bestOf,scoreMode:e.config.scoreMode,submissions:[],checkIn:{a:false,b:false},notes:'',...extra}}
function roundName(r,total){let n=total-r;return n===1?'GRAND FINAL':n===2?'SEMIFINALS':n===3?'QUARTERFINALS':'ROUND '+(r+1)}
function propagate(e=current()){let changed=true,steps=0;while(changed&&steps++<=e.matches.length+1){changed=false;for(let m of e.matches.filter(m=>m.kind==='bracket')){if(!m.settled&&m.aKnown&&m.bKnown&&(!m.a||!m.b)){m.settled=true;m.auto=true;m.winner=m.a||m.b||null;changed=true}if(m.settled&&m.next){let target=e.matches.find(x=>x.id===m.next),slot=m.nextSlot;if(target&&(!target[slot+'Known']||target[slot]!==m.winner)){target[slot]=m.winner;target[slot+'Known']=true;changed=true}}}}}
async function generateFixtures(){if(!allowed())return;let e=current(),approved=e.teams.filter(t=>t.status==='approved');if(approved.length<2){toast('Approve at least two squads to generate fixtures.');return}if(e.config.registration!=='closed'){toast('Close squad registration in Event Control first.');return}let predicted=e.config.format==='roundrobin'?approved.length*(approved.length-1)/2:2**Math.ceil(Math.log2(approved.length))-1;if(predicted>1000&&!confirm('This creates '+predicted+' fixtures and may be slow on this device. Continue?'))return;if(e.matches.length&&!confirm('Replace all matches, score evidence and disputes for this event?'))return;e.matches=[];e.disputes=[];let ids=approved.map(t=>t.id);for(let i=ids.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[ids[i],ids[j]]=[ids[j],ids[i]]}if(e.config.format==='roundrobin'){for(let i=0;i<ids.length;i++)for(let j=i+1;j<ids.length;j++)e.matches.push(createMatch(e,ids[i],ids[j],{kind:'league',ranked:true,group:'LEAGUE'}))}else{let size=2**Math.ceil(Math.log2(ids.length)),rounds=Math.log2(size),levels=[];let slots=[];let byes=size-ids.length,at=0;for(let i=0;i<size/2;i++){if(i<byes)slots.push(ids[at++],null);else slots.push(ids[at++],ids[at++])}for(let r=0;r<rounds;r++){let row=[];for(let i=0;i<size/2**(r+1);i++){let m=createMatch(e,r===0?slots[i*2]:null,r===0?slots[i*2+1]:null,{kind:'bracket',ranked:true,round:r,group:roundName(r,rounds),aKnown:r===0,bKnown:r===0});e.matches.push(m);row.push(m)}levels.push(row)}for(let r=0;r<levels.length-1;r++)levels[r].forEach((m,i)=>{m.next=levels[r+1][Math.floor(i/2)].id;m.nextSlot=i%2===0?'a':'b';levels[r+1][Math.floor(i/2)].parents.push(m.id)});propagate(e)}log('Fixtures generated: '+e.matches.length+' matches');if(!await save())return;go('matches');toast('Fixtures generated. Byes advance automatically.')}
function matchPage(){let e=current();return heading('COMPETITION CONTROL',db.labels.matches,'Custom matches, dynamic fixtures, schedules and check-ins.',organizer()?`<div class="quickrow"><button onclick="manualMatchForm()">+ CUSTOM MATCH</button><button class="primary" onclick="generateFixtures()">GENERATE FIXTURES</button></div>`:'')+`<div class="filters"><input id="matchSearch" type="search" placeholder="Search match or squad" aria-label="Search matches"><select id="matchFilter" aria-label="Filter matches"><option value="all">All match statuses</option>${['ready','scheduled','pending','disputed','complete','draw','bye','waiting'].map(s=>`<option>${s}</option>`).join('')}</select></div><div id="matchList">${matchList(e.matches)}</div>`}
function matchList(rows){let e=current(),bracket=rows.filter(m=>m.kind==='bracket'),other=rows.filter(m=>m.kind!=='bracket'),html='';if(bracket.length){let rounds=[...new Set(bracket.map(m=>m.round))].sort((a,b)=>a-b);html+=`<div class="legend"><span>BYE = automatic advancement</span><span>Scroll sideways to see all rounds</span></div><div class="boardwrap"><div class="roundGrid">${rounds.map(r=>`<section class="roundCol"><h3>${E(bracket.find(m=>m.round===r).group)}</h3>${bracket.filter(m=>m.round===r).map(matchCard).join('')}</section>`).join('')}</div></div>`}if(other.length)html+=`<div class="sectionhead"><h2>LEAGUE / CUSTOM MATCHES</h2><span class="noticeCount">${other.length} matchups</span></div><div class="matchGrid">${other.map(matchCard).join('')}</div>`;return html||empty('No matches yet. Generate fixtures or create a custom matchup.')}
function filterMatches(){let q=$('matchSearch').value.toLowerCase(),f=$('matchFilter').value;$('matchList').innerHTML=matchList(current().matches.filter(m=>(m.name+' '+tn(m.a)+' '+tn(m.b)).toLowerCase().includes(q)&&(f==='all'||status(m)===f)))}
function matchCard(m){let s=status(m);return `<article class="match"><div class="resultName"><strong>${E(m.name)}</strong><span class="badge ${s}">${s}</span></div><div class="subtitle">${E(m.group)} · ${m.scoreMode==='series'?'BO'+m.bestOf:'POINTS'}${m.ranked?' · RANKED':''}</div><div class="row ${m.winner&&m.winner===m.a?'win':''}"><span>${m.a?E(tn(m.a)):m.aKnown?'BYE':'Awaiting contender'}</span><strong>${m.score?.[0]??'—'}</strong></div><div class="row ${m.winner&&m.winner===m.b?'win':''}"><span>${m.b?E(tn(m.b)):m.bKnown?'BYE':'Awaiting contender'}</span><strong>${m.score?.[1]??'—'}</strong></div><small style="margin-top:12px">${E(timeText(m))}</small>${m.a&&m.b?`<small>Check-in: ${m.checkIn.a?'A ✓':'A —'} / ${m.checkIn.b?'B ✓':'B —'}</small>`:''}<div class="smallActions">${organizer()&&m.a&&m.b&&!m.settled?`<button onclick="scheduleForm('${m.id}')">Schedule</button>`:''}${role!=='viewer'&&m.a&&m.b&&!m.settled?`<button onclick="scoreForm('${m.id}')">Submit result</button><button onclick="checkIn('${m.id}')">Check-in</button>`:''}${organizer()?`<button onclick="matchDetails('${m.id}')">Details</button>${m.settled&&!m.auto?`<button onclick="resetResult('${m.id}')">Reset result</button>`:''}${m.kind==='friendly'?`<button class="danger" onclick="deleteMatch('${m.id}')">Delete</button>`:''}`:''}</div></article>`}
function manualMatchForm(){if(!allowed())return;let rows=current().teams.filter(t=>t.status==='approved');if(rows.length<2){toast('Approve at least two squads first.');return}openDialog('CREATE A CUSTOM MATCH',`<form id="manualMatch"><label for="matchName">Match name</label><input id="matchName" required maxlength="100" placeholder="Name your matchup"><div class="formgrid"><div><label for="teamA">First squad</label><select id="teamA">${rows.map(t=>`<option value="${t.id}">${E(t.name)}</option>`).join('')}</select></div><div><label for="teamB">Second squad</label><select id="teamB">${rows.map((t,i)=>`<option value="${t.id}" ${i===1?'selected':''}>${E(t.name)}</option>`).join('')}</select></div></div><label for="matchGroup">Stage / group name</label><input id="matchGroup" maxlength="60" value="Custom match"><div class="checklist"><label><input type="checkbox" id="ranked">Count this match in the leaderboard</label></div><p class="formHelp">Custom matches do not advance the generated knockout bracket.</p><p id="manualError" class="error" role="alert"></p><button class="primary">CREATE MATCH →</button></form>`);$('manualMatch').onsubmit=async ev=>{ev.preventDefault();let a=$('teamA').value,b=$('teamB').value,name=$('matchName').value.trim();if(a===b||!name){$('manualError').textContent='Choose two different squads and enter a match name.';return}let e=current();e.matches.push(createMatch(e,a,b,{name,group:$('matchGroup').value.trim()||'Custom match',ranked:$('ranked').checked}));log('Custom match created: '+name);if(!await save())return;closeDialog();render();toast('Match created.')}}
async function deleteMatch(mid){if(!allowed())return;let m=match(mid);if(m.kind!=='friendly')return;if(!confirm('Delete this custom match, its results and disputes?'))return;current().matches=current().matches.filter(m=>m.id!==mid);current().disputes=current().disputes.filter(d=>d.matchId!==mid);log('Custom match deleted');if(!await save())return;render()}
function matchDetails(mid){if(!allowed())return;let m=match(mid);openDialog('MATCH CONTROL',`<form id="detailsForm"><label for="detailName">Match name</label><input id="detailName" required maxlength="100" value="${E(m.name)}"><label for="detailGroup">Stage / group label</label><input id="detailGroup" required maxlength="60" value="${E(m.group)}"><label for="detailNotes">Match instructions / stream link / notes</label><textarea id="detailNotes" maxlength="5000">${E(m.notes)}</textarea><p class="formHelp">Format and bracket connections remain unchanged.</p><p id="detailsError" class="error"></p><button class="primary">SAVE MATCH DETAILS</button></form>`);$('detailsForm').onsubmit=async ev=>{ev.preventDefault();let name=$('detailName').value.trim(),group=$('detailGroup').value.trim();if(!name||!group){$('detailsError').textContent='Enter a match name and group label.';return}m.name=name;m.group=group;m.notes=$('detailNotes').value.trim();log('Match details updated: '+name);if(!await save())return;closeDialog();render();toast('Match details saved.')}}
function scheduleForm(mid){if(!allowed())return;let m=match(mid);openDialog('SCHEDULE THE BATTLE',`<p>${E(tn(m.a))} vs ${E(tn(m.b))}</p><form id="scheduleForm"><label for="matchTime">Date & start time (device local time)</label><input id="matchTime" type="datetime-local" required value="${E(m.time||'')}"><label for="duration">Expected duration (minutes)</label><input id="duration" type="number" min="1" step="1" required value="${m.duration}"><p id="scheduleError" class="error" role="alert"></p><button class="primary">SAVE SCHEDULE</button></form>`);$('scheduleForm').onsubmit=async ev=>{ev.preventDefault();let e=current(),t=$('matchTime').value,d=Number($('duration').value),start=new Date(t).getTime(),end=start+d*60000,err=$('scheduleError');if(!t||!Number.isFinite(start)||!Number.isSafeInteger(d)||d<1){err.textContent='Enter a valid time and positive whole-number duration.';return}if(e.config.date&&t.slice(0,10)<e.config.date){err.textContent='This is before the event start date.';return}if(e.matches.some(x=>x.id!==mid&&x.time&&[x.a,x.b].some(v=>v&&[m.a,m.b].includes(v))&&start<new Date(x.time).getTime()+x.duration*60000&&end>new Date(x.time).getTime())){err.textContent='Schedule conflict: a squad has an overlapping match.';return}if((m.parents||[]).map(x=>match(x)).filter(x=>x&&!x.auto).some(x=>!x.time||start<new Date(x.time).getTime()+x.duration*60000)){err.textContent='Schedule this round after its previous-round matches finish.';return}let next=m.next?match(m.next):null;if(next?.time&&end>new Date(next.time).getTime()){err.textContent='This match would end after its next-round match starts.';return}m.time=t;m.duration=d;log('Match scheduled: '+m.name);if(!await save())return;closeDialog();render();toast('Schedule saved.')}}
function checkIn(mid){if(role==='viewer')return;let m=match(mid);openDialog('MATCH CHECK-IN',`<p>${E(m.name)}</p><div class="stack"><button onclick="toggleCheckIn('${mid}','a')">${m.checkIn.a?'UNDO':'CONFIRM'} ${E(tn(m.a))}</button><button onclick="toggleCheckIn('${mid}','b')">${m.checkIn.b?'UNDO':'CONFIRM'} ${E(tn(m.b))}</button></div>`)}
async function toggleCheckIn(mid,slot){let m=match(mid);if(role==='viewer'||m.settled)return;m.checkIn[slot]=!m.checkIn[slot];log('Check-in updated: '+tn(m[slot]));if(!await save())return;closeDialog();render();toast('Check-in saved.')}
function validScore(m,a,b){if(![a,b].every(n=>Number.isSafeInteger(n)&&n>=0))return 'Scores must be non-negative whole numbers.';let e=current();if(a===b&&(m.kind==='bracket'||!e.config.allowDraw||m.scoreMode==='series'))return 'A draw is not allowed for this match.';if(m.scoreMode==='series'){let target=(m.bestOf+1)/2;if(Math.max(a,b)!==target||Math.min(a,b)>=target)return 'In BO'+m.bestOf+', the winner must reach '+target+' and the other score must be lower.'}return ''}
function scoreForm(mid){if(role==='viewer')return;let m=match(mid),e=current();if(!m.a||!m.b||m.settled)return;openDialog('SUBMIT YOUR MATCH RESULT',`<p>${E(tn(m.a))} vs ${E(tn(m.b))}</p>${m.notes?`<div class="note">${E(m.notes)}</div>`:''}<form id="scoreForm"><label for="submittedBy">Submitting squad</label><select id="submittedBy"><option value="${m.a}">${E(tn(m.a))}</option><option value="${m.b}">${E(tn(m.b))}</option></select><div class="formgrid"><div><label for="scoreA">${E(tn(m.a))} score</label><input type="number" id="scoreA" required min="0" step="1"></div><div><label for="scoreB">${E(tn(m.b))} score</label><input type="number" id="scoreB" required min="0" step="1"></div></div><p class="formHelp">${m.scoreMode==='series'?'Best of '+m.bestOf+' · First to '+((m.bestOf+1)/2):'Points scoring'} · ${e.config.allowDraw&&m.kind!=='bracket'&&m.scoreMode!=='series'?'Draws allowed':'No draws'}</p><label for="proof">Screenshot evidence (${e.config.proofRequired?'required':'optional'} · max 2 MB)</label><input id="proof" type="file" accept="image/png,image/jpeg,image/webp" ${e.config.proofRequired?'required':''}><label for="submissionNote">Result notes</label><textarea id="submissionNote" maxlength="2000"></textarea><p class="formHelp">Resubmitting keeps the previous submission in the review history.</p><p id="scoreError" class="error" role="alert"></p><button class="primary">SUBMIT FOR REVIEW</button></form>`);$('scoreForm').onsubmit=async ev=>{ev.preventDefault();let a=Number($('scoreA').value),b=Number($('scoreB').value),by=$('submittedBy').value,err=$('scoreError'),invalid=validScore(m,a,b);if(invalid){err.textContent=invalid;return}let file=$('proof').files[0];if(e.config.proofRequired&&!file){err.textContent='Attach the required evidence image.';return}let proof;try{proof=await readImage(file,2*1024*1024)}catch(x){err.textContent=x.message;return}m.submissions.push({id:uid(),by,a,b,proof,note:$('submissionNote').value.trim(),status:'pending',at:new Date().toISOString(),reviewNote:''});let pending=latest(m).filter(s=>s.status==='pending');if(pending.length===2&&(pending[0].a!==pending[1].a||pending[0].b!==pending[1].b)&&!openIssues(mid).some(d=>d.reason.startsWith('Conflicting score'))){e.disputes.push({id:uid(),matchId:mid,by:'System',title:'Conflicting result submissions',reason:'Conflicting score submissions require organizer review.',priority:'high',owner:'',due:'',status:'open',decision:'',history:[],at:new Date().toISOString()})}log('Result submitted: '+m.name);if(!await save())return;closeDialog();go('reviews');toast('Submission saved for review.')}}
function reviewPage(){let rows=current().matches.filter(m=>m.a&&m.b&&!m.auto);return heading('RESULT INTELLIGENCE',db.labels.reviews,'Evidence, revision history and organizer decisions.')+`<div class="stack">${rows.map(m=>`<section class="card"><div class="resultName resultHead"><div><div class="eventMeta">${E(m.group)} / ${E(m.name)}</div><h2>${E(tn(m.a))} vs ${E(tn(m.b))}</h2><span class="badge ${status(m)}">${status(m)}</span></div>${!m.settled&&role!=='viewer'?`<div class="quickrow"><button onclick="scoreForm('${m.id}')">Submit / revise</button><button onclick="disputeForm('${m.id}')">+ Dispute</button></div>`:''}</div>${m.settled?`<div class="scoreboard">${m.score?.[0]} : ${m.score?.[1]}</div><p class="success">${m.winner?'Winner: '+E(tn(m.winner)):'Draw confirmed'}</p>${organizer()?`<button onclick="resetResult('${m.id}')">RESET RESULT</button>`:''}`:latest(m).length?`<div class="two">${latest(m).map(s=>`<div class="submission"><strong>${E(tn(s.by))} / ${s.a} : ${s.b}</strong><span class="badge ${s.status}">${s.status}</span><p><small>${E(new Date(s.at).toLocaleString())}</small></p>${s.proof?`<img src="${s.proof}" alt="Submitted result evidence">`:'<p><small>No screenshot attached.</small></p>'}${s.note?`<p>${E(s.note)}</p>`:''}${s.reviewNote?`<div class="note">Review: ${E(s.reviewNote)}</div>`:''}${organizer()&&s.status==='pending'?`<div class="actions"><button class="primary" onclick="approveScore('${m.id}','${s.id}')" ${openIssues(m.id).length?'disabled':''}>APPROVE</button><button onclick="rejectScore('${m.id}','${s.id}')">REJECT / RETURN</button></div>`:''}</div>`).join('')}</div>`:empty('No result submitted yet.')}${openIssues(m.id).length?'<div class="note">Open disputes block approval. Resolve all active tickets for this match first.</div>':''}${m.submissions.length?`<div class="actions"><button onclick="submissionHistory('${m.id}')">VIEW HISTORY (${m.submissions.length})</button></div>`:''}</section>`).join('')||empty('Your review queue appears after matches are created.')}</div>`}
function applyScore(m,a,b){m.score=[a,b];m.winner=a===b?null:a>b?m.a:m.b;m.settled=true;m.auto=false;propagate()}
async function approveScore(mid,sid){if(!allowed())return;let m=match(mid),s=m.submissions.find(x=>x.id===sid);if(!s||m.settled)return;if(openIssues(mid).length){toast('Resolve all active disputes first.');return}let error=validScore(m,s.a,s.b);if(error){toast(error);return}if(!confirm('Approve '+s.a+' : '+s.b+' for '+m.name+'?'))return;s.status='approved';applyScore(m,s.a,s.b);log('Result approved: '+m.name);if(!await save())return;render();toast('Result confirmed. Progress and standings updated.')}
function rejectScore(mid,sid){if(!allowed())return;openDialog('RETURN RESULT FOR CORRECTION',`<form id="rejectForm"><label for="reviewReason">Reason / requested correction</label><textarea id="reviewReason" required maxlength="2000"></textarea><p id="rejectError" class="error"></p><button class="primary">RETURN SUBMISSION</button></form>`);$('rejectForm').onsubmit=async ev=>{ev.preventDefault();let note=$('reviewReason').value.trim();if(!note){$('rejectError').textContent='Enter the reason.';return}let s=match(mid).submissions.find(s=>s.id===sid);s.status='rejected';s.reviewNote=note;log('Submission returned: '+match(mid).name);if(!await save())return;closeDialog();render();toast('Submission returned. The squad can revise it.')}}
function submissionHistory(mid){let m=match(mid);openDialog('RESULT REVISION HISTORY',`<div class="stack">${m.submissions.slice().reverse().map(s=>`<div class="submission"><strong>${E(tn(s.by))} · ${s.a} : ${s.b}</strong><p>${E(new Date(s.at).toLocaleString())} · ${E(s.status)}</p>${s.note?`<p>${E(s.note)}</p>`:''}${s.reviewNote?`<p>Review: ${E(s.reviewNote)}</p>`:''}</div>`).join('')}</div>`)}
async function resetResult(mid){if(!allowed())return;let m=match(mid);if(m.auto)return;let ids=[],at=m;while(at){ids.push(at.id);at=at.next?match(at.next):null}if(!confirm('Reset this match plus '+(ids.length-1)+' dependent rounds, evidence and disputes?'))return;for(let id of ids){let x=match(id);x.score=null;x.winner=null;x.settled=false;x.auto=false;x.submissions=[];if(id!==mid){x.time=null;x.a=null;x.b=null;x.aKnown=false;x.bKnown=false;x.checkIn={a:false,b:false}}}current().disputes=current().disputes.filter(d=>!ids.includes(d.matchId));propagate();log('Result reset: '+m.name);if(!await save())return;render();toast('Result and dependent rounds reset safely.')}
function disputeForm(mid,did=null){if(role==='viewer')return;let m=match(mid),d=did?current().disputes.find(x=>x.id===did):null;if(m.settled&&!did){toast('Reset the confirmed result before opening a new dispute.');return}openDialog(d?'UPDATE DISPUTE TICKET':'OPEN A DISPUTE',`<form id="disputeForm"><label for="ticketTitle">Ticket title</label><input id="ticketTitle" required maxlength="120" value="${E(d?.title||'')}"><label for="ticketBy">Reporting squad</label><select id="ticketBy">${[m.a,m.b].filter(Boolean).map(t=>`<option value="${t}" ${d?.by===t?'selected':''}>${E(tn(t))}</option>`).join('')}${d?.by==='System'?'<option selected value="System">System</option>':''}</select><div class="formgrid"><div><label for="priority">Priority</label><select id="priority">${['low','medium','high'].map(p=>`<option ${p===(d?.priority||'medium')?'selected':''}>${p}</option>`).join('')}</select></div><div><label for="owner">Assigned reviewer</label><input id="owner" maxlength="100" value="${E(d?.owner||'')}"></div><div><label for="ticketDue">Review due date (optional)</label><input type="date" id="ticketDue" value="${E(d?.due||'')}"></div><div><label for="ticketStatus">Ticket status</label><select id="ticketStatus"><option value="open" ${d?.status==='open'?'selected':''}>Open</option><option value="inreview" ${d?.status==='inreview'?'selected':''}>In review</option></select></div></div><label for="reason">Reason and evidence explanation</label><textarea id="reason" required maxlength="10000">${E(d?.reason||'')}</textarea><p class="formHelp">Screenshot evidence is available on the match review screen.</p><p id="ticketError" class="error"></p><button class="primary">SAVE DISPUTE TICKET</button></form>`);$('disputeForm').onsubmit=async ev=>{ev.preventDefault();let reason=$('reason').value.trim(),title=$('ticketTitle').value.trim();if(!reason||!title){$('ticketError').textContent='Enter a title and reason.';return}let fields={title,reason,by:$('ticketBy').value,priority:$('priority').value,owner:$('owner').value.trim(),due:$('ticketDue').value,status:$('ticketStatus').value};if(d){Object.assign(d,fields);d.history.push({text:'Ticket updated',at:new Date().toISOString()})}else current().disputes.push({id:uid(),matchId:mid,...fields,decision:'',history:[],at:new Date().toISOString()});log('Dispute ticket saved: '+title);if(!await save())return;closeDialog();go('disputes');toast('Dispute saved.')}}
function disputePage(){return heading('FAIR PLAY CONTROL',db.labels.disputes,'Priority, ownership, deadlines and resolution history.')+`<div class="stack">${current().disputes.slice().sort((a,b)=>Number(a.status==='resolved')-Number(b.status==='resolved')).map(d=>{let m=match(d.matchId);return `<section class="card bulletin"><div class="resultName"><div><div class="eventMeta">${E(m?.name)} / ${E(tn(m?.a))} vs ${E(tn(m?.b))}</div><h2>${E(d.title||'Match dispute')}</h2></div><span class="badge ${d.status==='resolved'?'complete':'disputed'}">${d.status==='inreview'?'in review':d.status}</span></div><div class="chiprow"><span class="badge priority-${d.priority}">${E(d.priority)} priority</span><span class="badge">Reviewer: ${E(d.owner||'Unassigned')}</span>${d.due?`<span class="badge">Due: ${E(d.due)}</span>`:''}</div><p>Reporter: ${d.by==='System'?'System':E(tn(d.by))}</p><div class="bodyText">${E(d.reason)}</div>${d.decision?`<div class="note">Decision: ${E(d.decision)}</div>`:''}<div class="actions">${organizer()&&d.status!=='resolved'?`<button onclick="disputeForm('${d.matchId}','${d.id}')">EDIT / ASSIGN</button><button class="primary" onclick="resolveDispute('${d.id}')">RESOLVE TICKET</button>`:''}<button onclick="go('reviews')">MATCH EVIDENCE</button><button onclick="ticketHistory('${d.id}')">TICKET HISTORY</button></div></section>`}).join('')||empty('No dispute tickets. Create tickets from a match review screen.')}</div>`}
function resolveDispute(did){if(!allowed())return;let d=current().disputes.find(d=>d.id===did),m=match(d.matchId);openDialog('RESOLVE THE DISPUTE',`<p>${E(d.title)}</p><form id="resolveForm"><label for="decision">Decision and explanation</label><textarea id="decision" required maxlength="10000"></textarea><label for="chosenResult">Score action</label><select id="chosenResult"><option value="none">Resolve ticket only</option><option value="fresh">Resolve + request new evidence</option>${latest(m).filter(s=>s.status==='pending').map(s=>`<option value="${s.id}">${E(tn(s.by))}: ${s.a} : ${s.b}</option>`).join('')}</select><p id="resolveError" class="error"></p><button class="primary">CONFIRM ORGANIZER DECISION</button></form>`);$('resolveForm').onsubmit=async ev=>{ev.preventDefault();let text=$('decision').value.trim(),choice=$('chosenResult').value,err=$('resolveError');if(!text){err.textContent='Provide a decision explanation.';return}if(!['none','fresh'].includes(choice)&&openIssues(m.id).some(x=>x.id!==did)){err.textContent='Other tickets are still open. Resolve them before confirming a score.';return}if(!['none','fresh'].includes(choice)){let s=m.submissions.find(x=>x.id===choice),bad=validScore(m,s.a,s.b);if(bad){err.textContent=bad;return}s.status='approved';applyScore(m,s.a,s.b)}else if(choice==='fresh'){m.submissions.forEach(s=>{if(s.status==='pending'){s.status='rejected';s.reviewNote='Fresh evidence requested after dispute resolution.'}})}d.status='resolved';d.decision=text;d.history.push({text:'Resolved: '+text,at:new Date().toISOString()});log('Dispute resolved: '+d.title);if(!await save())return;closeDialog();render();toast('Resolution saved.')}}
function ticketHistory(did){let d=current().disputes.find(d=>d.id===did);openDialog('DISPUTE HISTORY',`<div class="note">Created: ${E(new Date(d.at).toLocaleString())}</div>${d.history.map(h=>`<div class="submission"><p>${E(h.text)}</p><small>${E(new Date(h.at).toLocaleString())}</small></div>`).join('')||empty('No updates yet.')}`)}
function standings(){let e=current(),rows=new Map(e.teams.filter(t=>t.status==='approved').map(t=>[t.id,{id:t.id,name:t.name,played:0,wins:0,draws:0,losses:0,scored:0,against:0,points:0}]));for(let m of e.matches.filter(m=>m.ranked&&m.settled&&!m.auto&&m.score)){let a=rows.get(m.a),b=rows.get(m.b);if(!a||!b)continue;a.played++;b.played++;a.scored+=m.score[0];a.against+=m.score[1];b.scored+=m.score[1];b.against+=m.score[0];if(m.winner){let w=m.winner===m.a?a:b,l=m.winner===m.a?b:a;w.wins++;l.losses++;w.points+=e.config.winPoints}else{a.draws++;b.draws++;a.points+=e.config.drawPoints;b.points+=e.config.drawPoints}}return [...rows.values()].sort((a,b)=>b.points-a.points||b.wins-a.wins||(b.scored-b.against)-(a.scored-a.against)||a.name.localeCompare(b.name))}
function leaderboardPage(){let rows=standings();return heading('RANKED INTELLIGENCE','THE LEADERBOARD.','Ranked matches only. Byes and unranked friendlies do not count.',organizer()?'<button onclick="exportStandings()">EXPORT CSV ↓</button>':'')+(rows.length?`<div class="tablewrap"><table class="table"><thead><tr><th>Rank</th><th>Squad</th><th>Played</th><th>W</th><th>D</th><th>L</th><th>Score +/−</th><th>Points</th></tr></thead><tbody>${rows.map((t,i)=>`<tr class="${i===0?'rank1':''}"><td><span class="rankBadge">${i+1}</span></td><td>${E(t.name)}</td><td>${t.played}</td><td>${t.wins}</td><td>${t.draws}</td><td>${t.losses}</td><td>${t.scored-t.against}</td><td>${t.points}</td></tr>`).join('')}</tbody></table></div><div class="note">Tie-break order: points → wins → score difference → squad name. A knockout champion is decided by the final, not this ranking.</div>`:empty('Approve your squads to populate the standings.'))}
function download(name,data,type){let url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function csvCell(v){let s=String(v);if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}
function exportStandings(){download('ArenaHub-standings.csv',[['Rank','Squad','Played','Wins','Draws','Losses','Score difference','Points'],...standings().map((r,i)=>[i+1,r.name,r.played,r.wins,r.draws,r.losses,r.scored-r.against,r.points])].map(r=>r.map(csvCell).join(',')).join('\r\n'),'text/csv');toast('Standings exported.')}
function announcementPage(){return heading('EVENT COMMS','YOUR TOURNAMENT BULLETINS.','Schedule notices, rule updates and organizer announcements.',organizer()?'<button class="primary" onclick="announcementForm()">+ NEW BULLETIN</button>':'')+`<div class="stack">${current().announcements.slice().sort((a,b)=>Number(b.pinned)-Number(a.pinned)).map(n=>`<article class="card bulletin"><div class="resultName"><h2>${E(n.title)}</h2><span class="badge">${n.pinned?'Pinned':E(n.priority)}</span></div><div class="bodyText">${E(n.body)}</div><p><small>${E(new Date(n.at).toLocaleString())}</small></p>${organizer()?`<div class="actions"><button onclick="announcementForm('${n.id}')">EDIT</button><button class="danger" onclick="deleteAnnouncement('${n.id}')">DELETE</button></div>`:''}</article>`).join('')||empty('No bulletins yet. Publish your first event update.')}</div>`}
function announcementForm(id=null){if(!allowed())return;let n=current().announcements.find(n=>n.id===id);openDialog('EVENT BULLETIN',`<form id="bulletinForm"><label for="bulletinTitle">Title</label><input id="bulletinTitle" required maxlength="150" value="${E(n?.title||'')}"><label for="bulletinBody">Announcement</label><textarea id="bulletinBody" required maxlength="20000">${E(n?.body||'')}</textarea><label for="bulletinPriority">Priority</label><select id="bulletinPriority">${['normal','important','urgent'].map(p=>`<option ${p===(n?.priority||'normal')?'selected':''}>${p}</option>`).join('')}</select><div class="checklist"><label><input id="pinned" type="checkbox" ${n?.pinned?'checked':''}>Pin this announcement</label></div><p id="bulletinError" class="error"></p><button class="primary">PUBLISH BULLETIN</button></form>`);$('bulletinForm').onsubmit=async ev=>{ev.preventDefault();let title=$('bulletinTitle').value.trim(),body=$('bulletinBody').value.trim();if(!title||!body){$('bulletinError').textContent='Enter a title and announcement.';return}let record={title,body,priority:$('bulletinPriority').value,pinned:$('pinned').checked,at:new Date().toISOString()};if(n)Object.assign(n,record);else current().announcements.unshift({id:uid(),...record});log('Bulletin published: '+title);if(!await save())return;closeDialog();render();toast('Bulletin saved.')}}
async function deleteAnnouncement(id){if(!allowed()||!confirm('Delete this bulletin?'))return;current().announcements=current().announcements.filter(n=>n.id!==id);log('Bulletin deleted');if(!await save())return;render()}
function rulesPage(){let e=current(),c=e.config;return heading('COMPETITION CODE','YOUR EVENT RULEBOOK.','Live rules based on your event configuration.')+`<div class="two"><section class="card"><div class="sectionLabel">SQUAD ENTRY</div><h2>${E(e.name)}</h2><ul class="rules"><li>${E(c.game)} · ${c.rosterSize} players per squad.</li><li>${c.maxTeams?'Maximum '+c.maxTeams+' active squad registrations.':'No fixed squad limit. Device capacity applies.'}</li><li>Squad names and player IDs must be unique within this event.</li><li>New and edited rosters require organizer approval.</li><li>${c.deadline?'Entry deadline: '+E(c.deadline)+'.':'No date-based entry deadline has been set.'}</li><li>${c.lockRosters?'Rosters lock when fixtures exist.':'Rosters may be edited while registration is open; edits require reapproval.'}</li></ul></section><section class="card"><div class="sectionLabel">MATCH PROTOCOL</div><h2>Scoring & fair play</h2><ul class="rules"><li>${c.format==='knockout'?'Single elimination with automatic byes for uneven brackets.':'Round robin: every unique squad pairing plays once.'}</li><li>${c.scoreMode==='series'?'Best of '+c.bestOf+'; first to '+((c.bestOf+1)/2)+' wins.':'Non-negative whole-number points scores.'}</li><li>${c.allowDraw&&c.scoreMode==='points'?'Draws are allowed outside knockout brackets.':'Draws are not allowed.'}</li><li>${c.proofRequired?'Screenshot evidence is required.':'Screenshot evidence is optional.'} Images may be PNG/JPG/WebP up to 2 MB.</li><li>Results remain pending until an organizer confirms them.</li><li>Open dispute tickets block score approval.</li><li>Leaderboard points: ${c.winPoints} per win; ${c.drawPoints} per draw. Byes and unranked matches are excluded.</li><li>Squad match schedules cannot overlap.</li></ul></section></div><section class="card" style="margin-top:20px"><div class="sectionLabel">ADDITIONAL RULES</div><div class="bodyText">${E(c.rules||'No additional event rules have been published.')}</div></section>`}
function settingsPage(){let e=current();return heading('COMMAND CENTER','CONFIGURE YOUR COMPETITION.','Change limits, scoring, rules and registration access.')+(organizer()?`<div class="two"><section class="card"><div class="sectionLabel">EVENT CONFIGURATION</div><form id="eventSettings">${eventFields(e)}</form></section><section class="card"><div class="sectionLabel">REGISTRATION CONTROL</div><h2>Squad access</h2><p>Registration is ${e.config.registration}. ${pastDeadline()?'The entry deadline has passed.':''}</p><div class="actions"><button onclick="toggleRegistration()">${e.config.registration==='open'?'CLOSE REGISTRATION':'REOPEN REGISTRATION'}</button></div><div class="note">Reopening does not erase fixtures. Roster editing may remain locked if the roster-lock option is enabled.</div><h2>Match operations</h2><div class="kv"><span>Squads</span><strong>${e.teams.length}</strong></div><div class="kv"><span>Matches</span><strong>${e.matches.length}</strong></div><div class="kv"><span>Review submissions</span><strong>${e.matches.reduce((n,m)=>n+m.submissions.length,0)}</strong></div><div class="kv"><span>Dispute tickets</span><strong>${e.disputes.length}</strong></div><div class="actions"><button onclick="generateFixtures()">GENERATE FIXTURES</button><button class="danger" onclick="clearFixtures()">CLEAR MATCHES</button></div><p><small>Clearing matches also clears their evidence and disputes. Squads and announcements remain saved.</small></p><hr class="softDivider"><h2>Device backup</h2><p>Export every tournament, roster, image and result in one backup.</p><div class="actions"><button onclick="exportBackup()">EXPORT BACKUP ↓</button><button onclick="importBackup()">IMPORT BACKUP ↑</button></div><hr class="softDivider"><h2>Delete tournament</h2><p>Only this event and its records will be removed.</p><button class="danger" onclick="deleteEvent('${e.id}')">DELETE THIS EVENT</button></section></div>`:empty('Open Organizer workspace to configure this event.'))}
async function toggleRegistration(){if(!allowed())return;let e=current();e.config.registration=e.config.registration==='open'?'closed':'open';log('Registration '+e.config.registration);if(!await save())return;render();toast('Registration access updated.')}
async function clearFixtures(){if(!allowed()||!confirm('Clear all matches, screenshots, results and disputes for this event? Squads and bulletins remain.'))return;let e=current();e.matches=[];e.disputes=[];log('All event matches cleared');if(!await save())return;render();toast('Matches cleared. Squad registrations remain saved.')}
function personalizePage(){return heading('ARENA IDENTITY','MAKE THE APP YOURS.','Branding, themes, navigation names and device-wide backup.')+(organizer()?`<div class="two"><section class="card"><form id="personalForm"><label for="appBrand">App name</label><input id="appBrand" required maxlength="24" value="${E(db.brand)}"><label for="appTag">Brand tagline</label><input id="appTag" maxlength="60" value="${E(db.tagline)}"><label for="appHeadline">Lobby headline (up to two lines)</label><textarea id="appHeadline" maxlength="100">${E(db.headline)}</textarea><div class="formgrid"><div><label for="appTheme">Arena theme</label><select id="appTheme"><option value="violet" ${db.theme==='violet'?'selected':''}>Neon Violet</option><option value="cyan" ${db.theme==='cyan'?'selected':''}>Cyber Cyan</option><option value="green" ${db.theme==='green'?'selected':''}>Acid Green</option></select></div><div><label for="appAccent">Custom app accent</label><input id="appAccent" type="color" class="colorInput" value="${db.accent||'#b8a1ff'}"></div></div><div class="checklist"><label><input id="useAppAccent" type="checkbox" ${db.accent?'checked':''}>Use custom app accent (events can override it)</label></div><div class="fieldgroup"><h3>NAVIGATION NAMES</h3>${Object.entries(db.labels).map(([k,v])=>`<label for="label-${k}">${k}</label><input id="label-${k}" required maxlength="24" value="${E(v)}">`).join('')}</div><p id="personalError" class="error"></p><button class="primary">SAVE ARENA IDENTITY</button></form></section><section class="card"><div class="sectionLabel">YOUR DEVICE. YOUR RECORDS.</div><h2>Workspace overview</h2><div class="kv"><span>Tournaments</span><strong>${db.events.length}</strong></div><div class="kv"><span>Total squads</span><strong>${db.events.reduce((n,e)=>n+e.teams.length,0)}</strong></div><div class="kv"><span>Total matches</span><strong>${db.events.reduce((n,e)=>n+e.matches.length,0)}</strong></div><div class="actions"><button onclick="exportBackup()">EXPORT EVERYTHING ↓</button><button onclick="importBackup()">IMPORT BACKUP ↑</button></div><div class="note">Records stay in this browser on this device. Export before clearing browser data or moving your project.</div><h2>More than one competition</h2><p>Create separate events for different games, roster sizes, match formats and rules. The tournament selector keeps them organized.</p><button class="primary" onclick="eventForm()">+ CREATE TOURNAMENT</button></section></div>`:empty('Open Organizer workspace to personalize the app.'))}
function wirePersonalize(){$('personalForm').onsubmit=async ev=>{ev.preventDefault();let brand=$('appBrand').value.trim(),headline=$('appHeadline').value.trim(),labels={};for(let k of Object.keys(db.labels))labels[k]=$('label-'+k).value.trim();if(!brand||Object.values(labels).some(x=>!x)){ $('personalError').textContent='Enter an app name and all navigation names.';return}db.brand=brand;db.tagline=$('appTag').value.trim();db.headline=headline.split('\n').slice(0,2).join('\n');db.theme=$('appTheme').value;db.accent=$('useAppAccent').checked?$('appAccent').value:'';db.labels=labels;if(!await save())return;render();toast('Your arena identity is saved.')}}
function exportBackup(){if(!allowed())return;download('ArenaHub-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify({app:'ArenaHub',version:2,records:db},null,2),'application/json');toast('All tournaments exported.')}
const imageSafe=s=>s===''||typeof s==='string'&&/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(s);
function validateBackup(x){if(!x||x.appVersion!==2||typeof x.brand!=='string'||x.brand.length>24||typeof x.tagline!=='string'||typeof x.headline!=='string'||!['violet','cyan','green'].includes(x.theme)||!(x.accent===''||/^#[0-9a-f]{6}$/i.test(x.accent))||!x.labels||Object.keys(defaultLabels()).some(k=>typeof x.labels[k]!=='string'||x.labels[k].length>24)||!Array.isArray(x.events))return false;let eids=new Set();for(let e of x.events){if(!validId(e.id)||eids.has(e.id)||typeof e.name!=='string'||!e.config||![e.teams,e.matches,e.disputes,e.announcements,e.activity].every(Array.isArray))return false;eids.add(e.id);let c=e.config;if(typeof c.game!=='string'||!Number.isInteger(c.rosterSize)||c.rosterSize<1||c.rosterSize>100||!Number.isSafeInteger(c.maxTeams)||c.maxTeams<0||!['knockout','roundrobin'].includes(c.format)||!['points','series'].includes(c.scoreMode)||!Number.isSafeInteger(c.bestOf)||c.bestOf<1||c.bestOf%2!==1||![c.winPoints,c.drawPoints].every(n=>Number.isSafeInteger(n)&&n>=0)||!['open','closed'].includes(c.registration)||typeof c.rules!=='string'||![c.date,c.deadline].every(v=>typeof v==='string'&&(v===''||/^\d{4}-\d{2}-\d{2}$/.test(v)))||!['proofRequired','lockRosters','allowDraw'].every(k=>typeof c[k]==='boolean')||!(c.accent===''||/^#[0-9a-f]{6}$/i.test(c.accent)))return false;let tids=new Set();for(let t of e.teams){if(!validId(t.id)||tids.has(t.id)||typeof t.name!=='string'||typeof t.captain!=='string'||!['pending','approved','rejected'].includes(t.status)||!Array.isArray(t.players)||t.players.length!==c.rosterSize||t.players.some(p=>typeof p.name!=='string'||typeof p.pid!=='string')||!imageSafe(t.logo)||!/^#[0-9a-f]{6}$/i.test(t.color)||typeof t.notes!=='string'||typeof t.contact!=='string')return false;tids.add(t.id)}let mids=new Set(e.matches.map(m=>m.id));if(mids.size!==e.matches.length)return false;for(let m of e.matches){if(!validId(m.id)||typeof m.name!=='string'||typeof m.group!=='string'||typeof m.notes!=='string'||!['friendly','league','bracket'].includes(m.kind)||![m.a,m.b,m.winner].every(v=>v===null||tids.has(v))||!(m.next===null||mids.has(m.next))||!Array.isArray(m.parents)||m.parents.some(p=>!mids.has(p))||!Number.isInteger(m.round)||m.round<0||!Number.isSafeInteger(m.duration)||m.duration<1||!(m.time===null||typeof m.time==='string'&&Number.isFinite(new Date(m.time).getTime()))||!m.checkIn||!['a','b'].every(k=>typeof m.checkIn[k]==='boolean')||!['aKnown','bKnown','settled','auto','ranked'].every(k=>typeof m[k]==='boolean')||!['points','series'].includes(m.scoreMode)||!Number.isSafeInteger(m.bestOf)||m.bestOf<1||m.bestOf%2!==1||!Array.isArray(m.submissions))return false;if(m.score!==null&&(!Array.isArray(m.score)||m.score.length!==2||m.score.some(n=>!Number.isSafeInteger(n)||n<0)))return false;for(let s of m.submissions){if(!validId(s.id)||![m.a,m.b].includes(s.by)||![s.a,s.b].every(n=>Number.isSafeInteger(n)&&n>=0)||!imageSafe(s.proof)||typeof s.note!=='string'||typeof s.reviewNote!=='string'||!['pending','approved','rejected'].includes(s.status)||!Number.isFinite(new Date(s.at).getTime()))return false}if(m.kind==='bracket'&&m.next){let seen=new Set([m.id]),at=m;while(at.next){if(seen.has(at.next))return false;seen.add(at.next);at=e.matches.find(n=>n.id===at.next);if(!at)return false}}}for(let d of e.disputes){if(!validId(d.id)||!mids.has(d.matchId)||typeof d.title!=='string'||typeof d.reason!=='string'||typeof d.decision!=='string'||typeof d.owner!=='string'||!['open','inreview','resolved'].includes(d.status)||!['low','medium','high'].includes(d.priority)||!(d.by==='System'||tids.has(d.by))||typeof d.due!=='string'||!Array.isArray(d.history)||d.history.some(h=>typeof h.text!=='string'||!Number.isFinite(new Date(h.at).getTime())))return false}for(let n of e.announcements)if(!validId(n.id)||typeof n.title!=='string'||typeof n.body!=='string'||!['normal','important','urgent'].includes(n.priority)||typeof n.pinned!=='boolean'||!Number.isFinite(new Date(n.at).getTime()))return false;for(let a of e.activity)if(typeof a.text!=='string'||!Number.isFinite(new Date(a.at).getTime()))return false}return x.active===null||eids.has(x.active)}
function defaultLabels(){return {teams:'SQUAD ROSTERS',matches:'MATCH CENTER',reviews:'RESULT REVIEW',disputes:'DISPUTE DESK'}}
function importBackup(){if(!allowed())return;let input=$('backupFile');input.value='';input.onchange=async()=>{let file=input.files[0];if(!file)return;if(file.size>100*1024*1024){toast('Import files up to 100 MB at a time to protect device memory.');return}let data;try{let wrapper=JSON.parse(await file.text());if(wrapper.app!=='ArenaHub')throw Error();data=wrapper.version===1?migrate(wrapper.records):wrapper.records;if(!validateBackup(data))throw Error()}catch{toast('This is not a valid ArenaHub backup.');return}if(!confirm('Replace all current tournaments and records with this backup? Export your current data first if needed.'))return;db=data;if(!await save())return;go('overview');toast('Backup imported. All records restored.')};input.click()}
function searchPage(){let e=current(),q=query.toLowerCase();if(!e)return noEvent();let hits=[...e.teams.filter(t=>(t.name+' '+t.captain).toLowerCase().includes(q)).map(t=>({title:t.name,type:'Squad',route:'teams'})),...e.matches.filter(m=>(m.name+' '+tn(m.a)+' '+tn(m.b)).toLowerCase().includes(q)).map(m=>({title:m.name+' · '+tn(m.a)+' vs '+tn(m.b),type:'Match',route:'matches'})),...e.disputes.filter(d=>(d.title+' '+d.reason+' '+d.owner).toLowerCase().includes(q)).map(d=>({title:d.title,type:'Dispute',route:'disputes'})),...e.announcements.filter(n=>(n.title+' '+n.body).toLowerCase().includes(q)).map(n=>({title:n.title,type:'Bulletin',route:'announcements'}))];return heading('QUICK SEARCH','FIND YOUR NEXT ACTION.','Results for “'+query+'” in '+e.name)+(hits.length?hits.map(h=>`<div class="queryhit"><div><span class="badge">${h.type}</span><h3 style="margin-top:8px">${E(h.title)}</h3></div><button onclick="go('${h.route}')">OPEN →</button></div>`).join(''):empty('No matching records.'))}
$('closeDialog').onclick=closeDialog;$('dialog').addEventListener('close',()=>{if(!$('dialog').open)$('dialogBody').innerHTML=''});$('role').onchange=ev=>{role=ev.target.value;closeDialog();render()};$('eventSelect').onchange=ev=>switchEvent(ev.target.value);$('newEvent').onclick=eventForm;$('menuToggle').onclick=()=>{let open=$('sidebar').classList.toggle('expanded');$('menuToggle').setAttribute('aria-expanded',String(open))};document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));$('globalSearch').onkeydown=ev=>{if(ev.key==='Enter'){query=ev.target.value.trim();if(query){page='search';render()}}};init();
